  "An analysis that scores an object below its floor raises an in-app alert and a message on each channel that takes alerts.": "オブジェクトのスコアが下限を下回る分析は、アプリ内アラートと、アラートを受け取る各チャネルへのメッセージを発生させます。",
  "No floors set.": "下限は設定されていません。",
  "Score floors": "スコア下限",
