  "Add": "追加",
  "Alert thresholds saved": "アラートのしきい値を保存しました",
  "Save thresholds": "しきい値を保存",
  "Alerts": "アラート",
  "Who is told about what, and when: the thresholds that raise an alert and the channels that carry it. Alerts carry counts, rule ids and links, never record values.": "誰に何をいつ知らせるか：アラートを発生させるしきい値と、それを届けるチャネル。アラートには件数、ルール ID、リンクが含まれ、レコードの値は含まれません。",
  "Add a channel": "チャネルを追加",
  "These settings are read only for your role.": "このロールではこれらの設定は読み取り専用です。",
  "Alerts stay in the app: no channel is set up. Nobody is emailed or messaged when an alert fires or a digest is due. Add email, Slack, Teams or a webhook to send them out.": "アラートはアプリ内だけに表示されます。チャネルが設定されていません。アラートの発生時やダイジェストの送信時に、メールやメッセージは届きません。送信するには、メール、Slack、Teams、または Webhook を追加してください。",
  "Channels": "チャネル",
  "Where alerts and digests go outside the app. A board pack channel gets the board pack and the analyst workbook for the latest finished run, weekly on Monday mornings or monthly on the 1st.": "アラートとダイジェストをアプリの外に届ける先です。取締役会向け資料のチャネルには、最新の完了した実行の取締役会向け資料とアナリスト用ワークブックが、毎週月曜の朝または毎月 1 日に届きます。",
  "Alert channels": "アラートチャネル",
  "The channels could not be read. {apiErrorMessage}": "チャネルを読み込めませんでした。{apiErrorMessage}",
  "No alert channels. Add email, Slack, Teams or a webhook to send critical alerts and digests.": "アラートチャネルはありません。重大なアラートとダイジェストを送るには、メール、Slack、Teams、または Webhook を追加してください。",
  "The alert settings": "アラート設定",
  "Default digest": "既定のダイジェスト",
  "The summary the tenant gets by default, by email and Teams. Each person sets their own digest of open work under Preferences.": "テナントが既定でメールと Teams で受け取る概要です。各ユーザーは自分の未処理の作業のダイジェストを「設定」で指定します。",
  "Enter an email address": "メールアドレスを入力してください",
  "dq-team@company.com": "dq-team@company.com",
  "Teams webhook": "Teams Webhook",
  "Enter an https:// address": "https:// のアドレスを入力してください",
