  "Built-in roles cannot be changed. Copy one to start a custom role, then set exactly what it may do. Give a role for one system or object only, from a person's grants.": "組み込みロールは変更できません。コピーしてカスタムロールを作成し、許可する操作を正確に設定してください。特定のシステムやオブジェクトだけにロールを付与するには、ユーザーの付与から行います。",
  "Create a role": "ロールを作成",
  "The roles could not be read. {apiErrorMessage}": "ロールを読み込めませんでした。{apiErrorMessage}",
  "No roles yet. Built-in roles appear once the tenant is set up.": "ロールはまだありません。組み込みロールはテナントの設定後に表示されます。",
  "What each role may do": "各ロールができること",
  "The actions each role allows, by resource. Open a role to see or change its full matrix.": "リソースごとに各ロールが許可する操作。ロールを開くと、完全なマトリクスを確認または変更できます。",
