  "Objects this system extracts on a rhythm. A paused schedule keeps its settings.": "このシステムが定期的に抽出するオブジェクト。一時停止中のスケジュールは設定を保持します。",
  "The schedules could not be read.": "スケジュールを読み込めませんでした。",
