  "Recent jobs": "最近のジョブ",
  "Open a job for its stages and tables. A failed job that recorded how it started can be retried; a running job cannot be cancelled, because the API has no cancel.": "ジョブを開くと、ステージとテーブルを確認できます。開始方法を記録した失敗ジョブは再試行できます。API に取り消し機能がないため、実行中のジョブは取り消せません。",
  "No job has run yet.": "実行されたジョブはまだありません。",
  "Runs and jobs": "実行とジョブ",
  "Starting runs": "実行の開始",
  "Start work here and follow it in the job line. Everything below acts on one system at a time.": "ここで作業を開始し、ジョブラインで進捗を追います。以下の操作は一度に 1 つのシステムに対して行われます。",
  "No system is connected yet. Connect one from the landscape, then start an extraction here.": "接続されたシステムはまだありません。ランドスケープから接続し、ここで抽出を開始してください。",
  "{title}. They apply from the next analysis run": "{title}。次回の分析実行から適用されます",
  "Earlier runs keep the scoring they were scored under.": "以前の実行は、採点されたときのスコアリングを保持します。",
  "Dimension weights": "ディメンションの重み",
  "The score is each measured dimension times its weight. The weights must add up to 100.": "スコアは、測定した各ディメンションに重みを掛けたものです。重みの合計は 100 にする必要があります。",
  "0 to 100": "0～100",
  "The weights add up to 100.": "重みの合計は 100 です。",
  "The weights add up to {sum}. Adjust them to 100 to save.": "重みの合計は {sum} です。保存するには 100 に調整してください。",
  "Weights saved": "重みを保存しました",
  "Save weights": "重みを保存",
  "Use the DAMA defaults": "DAMA の既定値を使う",
  "Score bands": "スコア帯",
  "At or above target is on target (go), at or above warning is at risk, below that is failing. Critical marks the line below which an object is failing badly.": "目標以上は目標達成（Go）、警告以上はリスクあり、それ未満は不合格です。重大は、オブジェクトが大きく不合格となる境界を示します。",
  "Critical must not exceed warning, and warning must not exceed target.": "重大は警告を超えてはならず、警告は目標を超えてはなりません。",
  "Score bands saved": "スコア帯を保存しました",
  "Save bands": "スコア帯を保存",
  "Use the default bands": "既定のスコア帯を使う",
  "Cap rule and tolerance": "上限ルールと許容範囲",
  "One critical rule failing beyond its tolerance holds that object at 85; two or more hold it at 70. The caps are fixed. The tolerance says how many failing records count as beyond.": "許容範囲を超えて不合格となる重大ルールが 1 つあるとオブジェクトは 85 に、2 つ以上で 70 に抑えられます。上限は固定です。許容範囲は、何件の不合格レコードで超過とみなすかを決めます。",
  "Failing share, percent": "不合格の割合（%）",
  "At or above this share of the records checked.": "チェックしたレコードのうちこの割合以上。",
  "Failing records": "不合格レコード",
