  "Removes every run, report and audit row of this organisation, and its stored files, for good. A request issues a token that works after 24 hours, so a mistake can be caught. The purge log keeps the record of the deletion.": "この組織のすべての実行、レポート、監査行と保存ファイルを完全に削除します。申請すると 24 時間後に有効になるトークンが発行されるため、誤りに気付く余裕があります。削除の記録は削除ログに残ります。",
  "The purge can run now.": "削除を今すぐ実行できます。",
  "The purge can run after {executes_after}.": "削除は {executes_after} 以降に実行できます。",
  "Purge now": "今すぐ削除",
  "Forget this request": "この申請を破棄",
  "Request a purge": "削除を申請",
