  "What this deployment is licensed for. Plan changes and invoices are handled in Meridian HQ; this deployment keeps its data either way.": "このデプロイメントのライセンス内容。プランの変更と請求書は Meridian HQ で扱います。いずれの場合も、このデプロイメントのデータは保持されます。",
  "Check with Meridian HQ now": "今すぐ Meridian HQ で確認",
