  "You built this batch, so a second person approves it.": "このバッチはあなたが作成したため、承認は別のユーザーが行います。",
  "Approving acts on the whole batch. You can take it back from the notice that follows.": "承認はバッチ全体に適用されます。続いて表示される通知から取り消せます。",
  "Send to SAP hands the approved values over as a Migration Cockpit file. It cannot be taken back.": "「SAP に送信」は承認済みの値を Migration Cockpit のファイルとして引き渡します。取り消すことはできません。",
