  "How {score} is made": "{score} の算出方法",
  "No failing records are listed for {l} yet. Rows appear when an analysis finds rules with a fixable or suggested value.": "{l} の不合格レコードはまだありません。修正可能な値や提案値のあるルールを分析が見つけると、行が表示されます。",
  "Open Work": "作業を開く",
  "No fix batches for {l} yet. A batch starts when a steward accepts suggested values or imports a filled fix sheet.": "{l} の修正バッチはまだありません。スチュワードが提案値を受け入れるか、記入済みの修正シートをインポートするとバッチが作成されます。",
  "Feature impact for {l} is calculated from the rules that fail. It fills when the impact model has run for this object.": "{l} の機能への影響は、不合格のルールから算出されます。このオブジェクトで影響モデルが実行されると表示されます。",
  "Open the capping rules": "上限を課しているルールを開く",
  "No process step reads {l} yet. Process readiness fills when a step of the process model reads the fields of the object.": "{l} を読むプロセスステップはまだありません。プロセスモデルのステップがオブジェクトの項目を読むと、プロセス準備状況が表示されます。",
  "Lineage fills when a field map is loaded for {l}: it shows where its fields come from and which rules read them.": "{l} の項目マップが読み込まれると系譜が表示されます。項目の出どころと、それを読むルールがわかります。",
  "No glossary terms are linked to {l} yet. A data owner links a term to a field and it appears here.": "{l} にリンクされた用語集の用語はまだありません。データオーナーが用語を項目にリンクすると、ここに表示されます。",
  "No golden records for {l} yet. A match run creates them from the records that describe the same thing.": "{l} のゴールデンレコードはまだありません。マッチングの実行により、同じものを表すレコードから作成されます。",
  "Share of their open work that is not yet past its due date.": "未処理の作業のうち、まだ期限を過ぎていない割合。",
  " {n} {approvals_waiting, plural, one {batch waits} other {batches wait}} for your approval.": "{n} 件のバッチがあなたの承認を待っています。",
  "{n} of {n2} {peopleCount, plural, one {person holds} other {people hold}} open work: {n3} {open, plural, one {record} other {records}}, {n4} overdue.{mine}": "{n2} 人中 {n} 人に未処理の作業があります：レコード {n3} 件、期限超過 {n4} 件。{mine}",
  "The people could not be read. Check that the API is reachable, then retry.": "担当者を読み込めませんでした。API に接続できるか確認して、再試行してください。",
