  "{blocked} of {stepsCount} {stepsCount, plural, one {step} other {steps}} blocked": "{stepsCount} ステップ中 {blocked} ステップがブロック",
  "Edit the process model, its steps and the fields each step reads in the process designer. Changes there show here on the next run.": "プロセスモデル、そのステップ、各ステップが読み取るフィールドはプロセスデザイナーで編集します。変更は次回の実行でここに反映されます。",
  "The process readiness of {label} could not be read.": "{label} のプロセス準備状況を読み込めませんでした。",
  "No process step reads the fields of {label}. Process readiness fills for objects that a step of the process model reads, such as Material master in Procure to Pay; add the object to a step in the designer.": "{label} のフィールドを読み取るプロセスステップはありません。プロセス準備状況は、プロセスモデルのステップが読み取るオブジェクト（例: 調達から支払までの品目マスタ）に表示されます。デザイナーでオブジェクトをステップに追加してください。",
  "No process step is blocked by {label}. Every step that reads its fields is ready in this run.": "{label} によってブロックされているプロセスステップはありません。そのフィールドを読み取るステップは、この実行ですべて準備完了です。",
  "{blockedCount} of {stepsCount} process {stepsCount, plural, one {step is} other {steps are}} blocked by {label}: {map}{value}.": "{stepsCount} 件中 {blockedCount} 件のプロセスステップが {label} によってブロックされています: {map}{value}。",
  "{l1Id} step {number}": "{l1Id} ステップ {number}",
  "A step is blocked when a field it writes fails a critical or high rule, or passes under 70%. Failing counts are records, and a record can fail several rules.": "ステップが書き込むフィールドが重大または高のルールに違反するか、合格率が 70% 未満の場合、そのステップはブロックされます。不合格数はレコード数で、1 件のレコードが複数のルールに違反することがあります。",
  "The readiness of {label} could not be read for this run.": "この実行の {label} の準備状況を読み込めませんでした。",
  "The migration waves could not be read.": "移行ウェーブを読み込めませんでした。",
  "Open migration waves": "移行ウェーブを開く",
  "{label} is not in a migration wave yet. A lead adds it to a wave, and its verdict appears here.": "{label} はまだ移行ウェーブに含まれていません。リーダーがウェーブに追加すると、ここに判定が表示されます。",
