  "A rule that blocks or degrades several features is counted under each. Features come from the impact model for this run.": "複数の機能をブロックまたは低下させるルールは、それぞれの機能で数えます。機能はこの実行の影響モデルから取得しています。",
  "Ranked by value at risk{value}. Failing % is of {records_checked} records checked.": "リスク金額順{value}。不合格率は確認したレコード {records_checked} 件に対する割合です。",
