  "The shown score moved only {shownBefore} to {shownAfter}, because the cap holds it at {shownAfter}.": "上限により {shownAfter} に抑えられているため、表示スコアは {shownBefore} から {shownAfter} にしか変わっていません。",
  "Compare two runs": "2 つの実行を比較",
  "Earlier run": "以前の実行",
