  "{label} has no run history here yet. Each run adds a point once two runs have scored this object.": "{label} の実行履歴はまだありません。2 回の実行でこのオブジェクトがスコア付けされると、実行ごとに点が追加されます。",
  "Measured score of {label}, last {pointsCount} runs: {measured} on {label2}, {measured2} on {label3}{value}{value2}.": "{label} の測定スコア（直近 {pointsCount} 回の実行）: {label2} は {measured}、{label3} は {measured2}{value}{value2}。",
