  "No configuration area has been read for this system. Load the configuration to see the areas and the objects behind each.": "このシステムではまだ構成領域が読み込まれていません。構成を読み込むと、領域と各領域のオブジェクトが表示されます。",
  "{AREA_STATUS_WORD}, {tables_done} of {tables_total} objects": "{AREA_STATUS_WORD}、{tables_total} 件中 {tables_done} 件のオブジェクト",
