  "{live} of {objsCount} configuration objects were read live from the system; the other {count} fall back to the SAP standard baseline, and the rules that depend on them apply by default.": "{objsCount} 件中 {live} 件の構成オブジェクトをシステムから直接読み込みました。残りの {count} 件は SAP 標準ベースラインを使用し、それに依存するルールは既定どおり適用されます。",
