  "Config drift alerts": "構成ドリフトのアラート",
  "After a configuration load or sync, tell the owners of the objects whose rules read a changed table, and re-score them.": "構成の読み込みまたは同期の後、変更されたテーブルを読むルールを持つオブジェクトのオーナーに通知し、再スコアリングします。",
