  "Empty: no alert on a floor.": "空欄: 下限による警告なし。",
  "Automation saved": "自動化を保存しました",
  "Save automation": "自動化を保存",
  "Changing these needs the manage settings permission.": "これらの変更には設定管理の権限が必要です。",
  "Webhooks": "Webhook",
  "Managing webhooks": "Webhook の管理",
  "{n} active {n, plural, one {webhook} other {webhooks}}. Meridian posts a signed JSON event to each when it happens: ids, names and numbers, never SAP values. A failed post is retried 1, 2, 4 and 8 minutes later and marked failed after 5 attempts.": "有効な Webhook は {n} 件です。Meridian はイベントが起きると各 Webhook に署名付き JSON イベントを送信します。内容は ID、名前、数値のみで、SAP の値は含みません。送信に失敗すると 1、2、4、8 分後に再試行し、5 回失敗すると失敗として記録します。",
  "Add a webhook": "Webhook を追加",
  "The webhooks could not be read. {detail}": "Webhook を読み込めませんでした。{detail}",
  "No webhook yet. Add one with the URL of a Slack or Teams workflow, or any https endpoint, and the events it should receive.": "Webhook はまだありません。Slack または Teams のワークフロー、または任意の https エンドポイントの URL と受信するイベントを指定して追加してください。",
  "Automation": "自動化",
  "What Meridian does by itself after a configuration change, from stewards' fixes and when a score drops.": "構成の変更後、スチュワードの修正から、スコアが下がったときに Meridian が自動で行うこと。",
  "The automation settings": "自動化の設定",
  "Only records whose SAP change date is after the last full download of the same objects and scope are read; tables without change dates are read in full. The change log of the download shows what changed, table by table, under Extractions.": "同じオブジェクトと範囲の前回の完全ダウンロード以降に SAP の変更日があるレコードだけを読みます。変更日のないテーブルはすべて読みます。何が変わったかは、抽出の下にあるダウンロードの変更ログでテーブルごとに確認できます。",
