  "Slack workflow": "Slack ワークフロー",
  "Paste the URL of a Slack workflow that starts from a webhook. The workflow reads the event and the numbers from Meridian's JSON body.": "Webhook で開始する Slack ワークフローの URL を貼り付けてください。ワークフローは Meridian の JSON 本文からイベントと数値を読み取ります。",
