  "The server cannot reach the licence server, so features stay locked until it can. Ask your administrator to check the server's outbound access to Meridian HQ, then retry.": "サーバーがライセンスサーバーに接続できないため、接続できるまで機能はロックされたままです。サーバーから Meridian HQ への外向きの通信を管理者に確認してもらい、再試行してください。",
