  "Check with SAP first.": "先に SAP で確認してください。",
  "No field of this batch goes by BAPI; deliver it with the load file.": "このバッチには BAPI で送信できる項目がありません。ロードファイルで引き渡してください。",
  "Live write-back": "SAP への直接書き戻し",
  "This deployment writes approved values to SAP through its BAPIs. Check with SAP first: it says which fields a BAPI carries and why the others go out with the load file. Nothing is sent by the check.": "このデプロイメントは、承認済みの値を SAP の BAPI で書き戻します。まず SAP で確認してください。どの項目を BAPI で送信でき、他の項目がなぜロードファイルで引き渡されるかが表示されます。確認では何も送信されません。",
  "Checking with SAP needs the apply permission, which your role does not hold.": "SAP での確認には適用権限が必要ですが、あなたのロールにはありません。",
