  "Each count is of records, not issues: one record with three failed rules counts once. Chip counts follow the object, rule and person filters.": "件数は問題ではなくレコードの数です。3つのルールに違反したレコードも1件と数えます。チップの件数はオブジェクト、ルール、担当者のフィルターに従います。",
