  "Calibration needs {n} accepted and {n} rejected steward decisions. Decide more pairs above and the weights are learned from them.": "キャリブレーションには、スチュワードの承認 {n} 件と却下 {n} 件が必要です。上でさらにペアを判断すると、そこから重みが学習されます。",
