  "Firewall traffic by day table, scrollable": "日別ファイアウォール通信量の表、スクロール可",
  "Warned": "警告",
  "Rules that block most": "最もブロックしたルール",
  "Critical rules, most blocked records first.": "重大ルール、ブロック件数の多い順。",
  "No rule has blocked a record yet.": "まだレコードをブロックしたルールはありません。",
  "Top blocking rules table, scrollable": "ブロック数上位ルールの表、スクロール可",
  "The objects the licence covers.": "ライセンスの対象オブジェクト。",
  "Firewall traffic by object table, scrollable": "オブジェクト別ファイアウォール通信量の表、スクロール可",
  "Records that failed a rule, per run": "ルールに違反したレコード（実行ごと）",
