  "Below the minimum": "最小値未満",
  "Below the learned minimum": "学習した最小値未満",
  "Outside the usual range but smaller than the minimum a steward raised. Nothing is alerted. Confirm one that is real and the minimum drops.": "通常の範囲外ですが、スチュワードが引き上げた最小値より小さい差です。通知はされません。実際の問題であれば確認すると、最小値が下がります。",
  "Confirm as real": "実際の問題として確認",
  "No break sits below a raised minimum.": "引き上げられた最小値未満の逸脱はありません。",
  "Breaks below the learned minimum table, scrollable": "学習した最小値未満の逸脱の表、スクロール可",
  "Released to the SAP save": "SAP保存へ解放済み",
  "Held": "保留中",
  "Released": "解放済み",
  "Not held": "保留なし",
  "Waiting for the approval workflow. The SAP save stops.": "承認ワークフローの結果待ちです。SAPでの保存は止まります。",
  "Approved and released to the SAP save. The save may go on, even for a blocked record.": "承認済みでSAP保存へ解放されました。ブロックされたレコードでも保存を続行できます。",
  "Rejected by an approver. The SAP save stops. Changed content opens a new request.": "承認者が却下しました。SAPでの保存は止まります。内容を変更すると新しい申請が作成されます。",
  "Already taken as a load file. The SAP save stops, so the record is not created twice.": "すでにロードファイルとして取得済みです。レコードが二重に作成されないよう、SAPでの保存は止まります。",
  "Meridian writes or has written this record to SAP. The SAP save stops, so the record is not created twice.": "MeridianがこのレコードをSAPへ書き込み中、または書き込み済みです。二重作成を避けるため、SAPでの保存は止まります。",
  "Hold state of each record table, scrollable": "レコードごとの保留状態の表、スクロール可",
  "Hold": "保留",
  "What it means": "意味",
  "SAP has not given a key.": "SAPはキーをまだ付与していません。",
  "Holds": "保留",
  "A held record waits for the approval workflow before SAP may save it. Released, rejected and written count the last 7 days; held counts what waits now.": "保留されたレコードは、SAPが保存する前に承認ワークフローを待ちます。解放、却下、書き込みは直近7日間の件数で、保留は現在待っている件数です。",
  "Oldest held": "最も古い保留",
  "Nothing is held.": "保留中のものはありません。",
  "Median time to a decision": "判断までの時間の中央値",
  "Nothing was decided in the last 7 days.": "直近7日間に判断されたものはありません。",
  "No record is held.": "保留中のレコードはありません。",
  "Held requests table, scrollable": "保留中の申請の表、スクロール可",
  "Off: the verdict alone decides the save": "オフ: 判定だけで保存の可否を決める",
  "Blocked: hold blocked records for approval": "ブロック: ブロックされたレコードを承認まで保留",
  "Flagged: hold blocked and warned records for approval": "フラグ付き: ブロックと警告のレコードを承認まで保留",
  "The SAP save stops.": "SAPでの保存は止まります。",
  "The SAP save may go on.": "SAPでの保存を続行できます。",
  "{records} {n, plural, one {record is} other {records are}} written to SAP now, in chunks, by a background worker. Each is checked in a test run first, and SAP commits only a record whose answer holds no error. A committed change cannot be taken back from here.": "{records} 件のレコードを、バックグラウンド処理でチャンクごとに SAP へ書き込みます。各レコードはまずテスト実行で確認され、応答にエラーがないレコードだけが SAP でコミットされます。コミット済みの変更はここから取り消せません。",
  "A record to check in SAP may or may not have been committed. Look it up in SAP before you send it again.": "SAP で確認が必要なレコードは、コミットされた可能性があります。再送する前に SAP で確認してください。",
  "Cancel run": "実行を取り消す",
  "Cancelling": "取り消し中",
  "Committed": "コミット済み",
  "Next page": "次のページ",
  "No reason stored": "理由は保存されていません",
  "No worker has reported on this run for a while. Resume it to continue; a record that was in flight is marked to check in SAP and is not sent again.": "しばらくこの実行について処理側からの報告がありません。再開して続行してください。送信中だったレコードは SAP での確認対象になり、再送されません。",
  "Paused: {reason}": "一時停止: {reason}",
  "Previous page": "前のページ",
  "Records handled by the write-back": "書き戻しで処理済みのレコード",
  "Records SAP refused or that need a check": "SAP が拒否した、または確認が必要なレコード",
  "Checked in SAP, send again": "SAPで確認済み、再送信",
  "Retry failed": "失敗分を再試行",
  "SAP message": "SAP メッセージ",
  "Sent {sent} of {records}, refused {failed}, to check {check}, waiting {pending}.": "{records} 件中 {sent} 件送信済み、{failed} 件拒否、{check} 件要確認、{pending} 件待機中。",
  "Sent with refusals": "送信済み(拒否あり)",
