  "No system": "システムなし",
  "{n} {n, plural, one {row} other {rows}} loaded and queued for checks": "{n} 行を読み込み、検査待ちにしました",
  "The source has more rows than the limit; only the first ones were read.": "ソースの行数が上限を超えているため、先頭の行だけを読み取りました。",
  "Loading…": "読み込み中…",
  "Load and check": "読み込んで検査",
  "Delete this connection?": "この接続を削除しますか?",
  "The stored password is removed. Runs already loaded stay.": "保存済みのパスワードは削除されます。読み込み済みの実行は残ります。",
  "Connection deleted": "接続を削除しました",
  "Database sources": "データベースソース",
  "Managing database sources": "データベースソースの管理",
  "Score data that lives outside SAP. Meridian reads one table or one SELECT, read only, then checks the rows with the same rules as a file upload. PostgreSQL is supported. SQL Server, Snowflake, Databricks and BigQuery are not.": "SAP外のデータを評価します。Meridianは1つのテーブルまたはSELECTを読み取り専用で読み込み、ファイルのアップロードと同じルールで検査します。対応はPostgreSQLのみで、SQL Server、Snowflake、Databricks、BigQueryには対応していません。",
  "Give the connection a database user that can only read. A read-only session does not stop a function that writes on the server.": "読み取り専用のデータベースユーザーを使ってください。読み取り専用セッションでも、サーバー上で書き込む関数は止められません。",
  "The connections could not be read. {detail}": "接続を読み取れませんでした。{detail}",
  "No connection yet. Add one with the host, database and a read-only user.": "接続がありません。ホスト、データベース、読み取り専用ユーザーで追加してください。",
  "Open a connection to read from it.": "接続を開いて読み取ります。",
  "Read a table or one SELECT from a non-SAP database and score the rows with the same rules as a file upload.": "SAP以外のデータベースからテーブルまたはSELECTを読み込み、ファイルのアップロードと同じルールで評価します。",
  "Analysis deleted": "分析を削除しました",
  "The analysis could not be deleted.": "分析を削除できませんでした。",
  "Delete the analysis of {d}": "{d}の分析を削除",
  "The analysis, its gaps, load files and reconciliations are removed, with the stored copies of the records. This cannot be undone.": "分析、そのギャップ、ロードファイル、照合は、保存されたレコードのコピーとともに削除されます。この操作は元に戻せません。",
  "Delete the analysis": "分析を削除",
  "Extraction of the target system started": "ターゲットシステムの抽出を開始しました",
  "The target system could not be extracted.": "ターゲットシステムを抽出できませんでした。",
  "The target system has not been extracted yet, so there is nothing to compare the load files with. The comparison starts by itself when the extraction has been analysed.": "ターゲットシステムはまだ抽出されていないため、ロードファイルと比較するものがありません。抽出の分析が終わると、比較は自動的に始まります。",
  "Extract the target system": "ターゲットシステムを抽出",
