  "Normal ranges and lead and lag links the Aletheia engine learned from the run trend.": "Aletheia エンジンが実行トレンドから学習した正常範囲と先行・遅行の関係。",
  "Three scored runs are needed before the engine can learn from the trend.": "エンジンがトレンドから学習するには、スコア付きの実行が 3 回必要です。",
  "This deployment runs without its Aletheia engine. An administrator can set it up.": "このデプロイメントは Aletheia エンジンなしで動作しています。管理者が設定できます。",
